use moloch_live_runtime::execution_edge::{self as edge,Config};
use moloch_replay::session::Session;
use serde_json::{Value,json};
use std::path::PathBuf;
const BASE:u64=1_792_022_400_000;
fn stamp(n:u64)->String{chrono::DateTime::from_timestamp_millis((BASE+n)as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn config()->Config{Config{fill_window_ms:1000,markout_ms:1000,post_window_ms:500,embargo_ms:500,maximum_book_age_ms:10_000,maximum_delivery_ms:1000,maximum_training_age_ms:60_000,minimum_samples:2,minimum_coverage_bps:9000,probability_haircut_bps:1000,uncertainty_per_share:5000,exit_fee_per_share:0,fee_policy_source_sha256:"a".repeat(64),maximum_keys:16,maximum_pending:16,retained_samples:8}}
struct F{path:PathBuf,bank:Session}
impl Drop for F{fn drop(&mut self){edge::clear_observer();let _=std::fs::remove_dir_all(&self.path);}}
impl F{
 fn new()->Self{let path=std::env::temp_dir().join(format!("shared-edge-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));let policy=json!({"initialCash":"100.000000","maximumCommitted":"40.000000","maximumMarketCost":"20.000000","quantity":2,"maximumMarkets":3,"minimumSpreadTicks":2,"entryStopAt":stamp(1_000_000)});let seed=json!({"runId":"observer-fixture","availableCash":"100.000000","accountSnapshotHash":"a".repeat(64),"observedAt":stamp(0)});let bank=Session::open_live(&path,&policy,&seed).unwrap();Self{path,bank}}
 fn commit(&mut self,source:&str,n:u64)->Value{let e=json!({"type":"tick","receivedAt":stamp(n),"processedAt":stamp(n)});let seq=self.bank.last_source_sequence(source)+1;assert!(self.bank.accept(source,seq,&e).unwrap());edge::observe_runtime_committed(&self.bank,source,seq,&e);e}
}
#[test]fn one_shared_observer_tracks_interleaved_actual_durable_ordinary_and_package_sources(){let mut f=F::new();edge::initialize_observer(&f.bank,Some(config())).unwrap();f.commit("moloch-live",1);f.commit("moloch-package",2);f.commit("moloch-live",3);f.commit("moloch-package",4);let d=edge::observer_diagnostic().unwrap();assert_eq!(d["disabled"],Value::Null);assert_eq!(d["committedSourceSequences"]["moloch-live"],2);assert_eq!(d["committedSourceSequences"]["moloch-package"],2);assert_eq!(d["lastObservedAtMs"],BASE+4);assert_eq!(d["diagnostics"]["attempted"],0);assert_eq!(d["executionAuthority"],false);assert!(f.bank.engine().fills().is_empty());}
#[test]fn false_committed_payload_disables_confidence_without_rejecting_later_native_events(){let mut f=F::new();edge::initialize_observer(&f.bank,Some(config())).unwrap();let mut actual=f.commit("moloch-package",1);let original=f.bank.durable_head();actual["processedAt"]=json!(stamp(2));edge::observe_runtime_committed(&f.bank,"moloch-package",1,&actual);assert_eq!(edge::observer_diagnostic().unwrap()["disabled"],"EDGE_SOURCE_BYTES_NOT_COMMITTED");assert_eq!(f.bank.durable_head(),original);f.commit("moloch-live",3);assert_eq!(f.bank.last_source_sequence("moloch-live"),1);assert_eq!(edge::observer_diagnostic().unwrap()["disabled"],"EDGE_SOURCE_BYTES_NOT_COMMITTED");assert!(f.bank.engine().fills().is_empty());}
#[test]fn cold_restart_starts_at_current_both_source_cursors_without_replaying_history(){let mut f=F::new();edge::clear_observer();f.commit("moloch-live",1);f.commit("moloch-package",2);f.commit("moloch-live",3);assert!(edge::observer_diagnostic().is_none());edge::initialize_observer(&f.bank,Some(config())).unwrap();let d=edge::observer_diagnostic().unwrap();assert_eq!(d["committedSourceSequences"]["moloch-live"],2);assert_eq!(d["committedSourceSequences"]["moloch-package"],1);assert_eq!(d["diagnostics"]["completed_marks"],0);f.commit("moloch-package",4);assert_eq!(edge::observer_diagnostic().unwrap()["disabled"],Value::Null);assert_eq!(edge::observer_diagnostic().unwrap()["committedSourceSequences"]["moloch-package"],2);}
#[test]fn observer_is_worker_thread_local_and_disabled_config_cannot_reuse_old_state(){let f=F::new();edge::initialize_observer(&f.bank,Some(config())).unwrap();std::thread::spawn(||{assert!(edge::observer_diagnostic().is_none());edge::clear_observer();}).join().unwrap();assert!(edge::observer_diagnostic().is_some());edge::initialize_observer(&f.bank,None).unwrap();assert!(edge::observer_diagnostic().is_none());}
#[test]fn actual_durable_daily_policy_change_requires_cold_model_reset_and_preserves_financial_prefix(){let mut f=F::new();edge::initialize_observer(&f.bank,Some(config())).unwrap();f.commit("moloch-package",1);let old=f.bank.engine().report().unwrap();let anchor=BASE+1_000_000;let end=anchor+86_400_000;let e=json!({"type":"live_entry_window","source":"moloch_live_dispatcher","receivedAt":stamp(1_000_000),"processedAt":stamp(1_000_000),"previousEntryStopAt":stamp(1_000_000),"entryStopAt":stamp(1_000_000+86_400_000),"mandate":{"authorizationId":"offline-fixture-daily","approvedAt":stamp(0),"anchorMs":anchor,"campaignEndMs":end,"intervalMs":86_400_000,"maximumCommitted":"40.000000","maximumMarketCost":"20.000000","maximumQuantity":2}});assert!(f.bank.accept("moloch-live",1,&e).unwrap());edge::observe_runtime_committed(&f.bank,"moloch-live",1,&e);assert_eq!(edge::observer_diagnostic().unwrap()["disabled"],"EDGE_BANK_OR_POLICY_CHANGED");let durable=f.bank.durable_head();edge::initialize_observer(&f.bank,Some(config())).unwrap();assert_eq!(f.bank.durable_head(),durable);let d=edge::observer_diagnostic().unwrap();assert_eq!(d["disabled"],Value::Null);assert_eq!(d["committedSourceSequences"]["moloch-live"],1);assert_eq!(d["committedSourceSequences"]["moloch-package"],1);assert_eq!(d["diagnostics"]["completed_marks"],0);f.commit("moloch-package",1_000_001);assert_eq!(edge::observer_diagnostic().unwrap()["disabled"],Value::Null);let after=f.bank.engine().report().unwrap();for k in ["cash","realized","fees","ownedCost","reservedCash"]{assert_eq!(old[k],after[k],"{k}");}}
#[test]fn actual_committed_ack_replay_after_complete_terminal_never_reintroduces_own_depth(){let mut f=F::new();edge::initialize_observer(&f.bank,Some(config())).unwrap();let event=json!({"type":"book","receivedAt":stamp(1),"processedAt":stamp(1),"book":{"tournamentId":"cup","marketId":"101","exchangeId":"101","sequence":"1","sourceAt":stamp(1),"requestStartedAt":stamp(1),"receivedAt":stamp(1),"bids":[{"price":"0.400000","quantity":100}],"asks":[{"price":"0.450000","quantity":100}]}});assert!(f.bank.accept("moloch-live",1,&event).unwrap());edge::observe_runtime_committed(&f.bank,"moloch-live",1,&event);let q=f.bank.engine().order_records().into_iter().find(|q|q["side"]=="YES"&&q["action"]=="buy").unwrap();let mut ack=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":q["id"],"actualOrderId":"901","exchangeId":q["exchangeId"],"marketId":q["marketId"],"side":q["side"],"action":q["action"],"quantity":q["quantity"],"price":q["price"],"receivedAt":stamp(3001),"processedAt":stamp(3001)});assert!(f.bank.accept("moloch-package",1,&ack).unwrap());edge::observe_runtime_committed(&f.bank,"moloch-package",1,&ack);assert_eq!(edge::observer_diagnostic().unwrap()["knownOwnLiquidityOrders"],1);let mut terminal=ack.clone();terminal["type"]=json!("actual_order_terminal");terminal["status"]=json!("canceled");terminal["fillsComplete"]=json!(true);terminal["filledQuantity"]=json!(0);terminal["receivedAt"]=json!(stamp(3002));terminal["processedAt"]=terminal["receivedAt"].clone();assert!(f.bank.accept("moloch-package",2,&terminal).unwrap());edge::observe_runtime_committed(&f.bank,"moloch-package",2,&terminal);assert_eq!(edge::observer_diagnostic().unwrap()["knownOwnLiquidityOrders"],0);assert_eq!(edge::observer_diagnostic().unwrap()["knownTerminalOrders"],1);ack["receivedAt"]=json!(stamp(3003));ack["processedAt"]=ack["receivedAt"].clone();let before=f.bank.engine().report().unwrap();assert!(f.bank.accept("moloch-package",3,&ack).unwrap());edge::observe_runtime_committed(&f.bank,"moloch-package",3,&ack);let d=edge::observer_diagnostic().unwrap();assert_eq!(d["disabled"],Value::Null);assert_eq!(d["knownOwnLiquidityOrders"],0);assert_eq!(d["knownTerminalOrders"],1);assert_eq!(d["committedSourceSequences"]["moloch-package"],3);let after=f.bank.engine().report().unwrap();for k in ["cash","ownedCost","realized","fees","reservedCash"]{assert_eq!(before[k],after[k]);}assert!(f.bank.engine().fills().is_empty());}
